  app.innerHTML=`<section class="scene mid-scene"><img src="./data/art/${archive?'forest-library':'windmill-village'}.png" alt="${title}の風景"><h1>${title}</h1><p>${archive?'木々の間にある文庫には、人と精霊が集めた本や記録が並んでいます。':'風車の音が響く里では、人と精霊が道具や灯りを手入れしています。'}</p><div class="characters"><figure><img src="./data/art/${archive?'aoi-pose-v3':'toma-pose-v2'}.png" alt="${role}、${name}の全身"><figcaption><strong>${name}</strong><br>${role}</figcaption></figure></div>${dialogue(speaker,line)}${dialogue('nono','どんなお手伝いができるかな？')}<p>手伝いたいことを選びましょう。もう一方も後から選べます。</p>${warning()}<h2>お手伝い</h2><div class="actions">${quests}${newButtons(region)}</div>${ready&&!state.bridgeOpen?'<h2>橋の出来事</h2><div class="actions"><button id="bridge">橋の開通を見届ける</button></div>':''}<h2>旅立ち</h2><div class="actions">${state.bridgeOpen?`<button id="cross">つながりの道を通って${archive?'風車の里':'森の文庫'}へ</button>`:''}<button id="travel">旅先を選ぶ</button></div></section>`;
  bindNewButtons();app.querySelectorAll('[data-mid-quest]').forEach(button=>button.onclick=()=>{state.midActive=button.dataset.midQuest;state.midDrafts[state.midActive]??=[];show('mid-quest');});
  if(archive&&state.storyClimaxComplete&&festivalReady(state.completed)){const ready=['archive-version-snapshot','archive-version-merge'].every(id=>state.completed.includes(id)),section=document.createElement('section');section.className='panel';section.innerHTML=`<h2>道案内帳の版を整える依頼</h2><p>アオイと案内帳の変更を確かめましょう。</p><div class="actions"><button id="version-snapshot">記録した版を見比べる${state.completed.includes('archive-version-snapshot')?'（達成済み）':''}</button><button id="version-merge">二人の変更を合わせる${state.completed.includes('archive-version-merge')?'（達成済み）':''}</button>${ready?`<button id="version-release">公開する版を確かめる${state.completed.includes('archive-version-release')?'（達成済み）':''}</button>`:''}</div>${ready?'':'<p>二つのお手伝いを終えると、公開する版の相談が届きます。</p>'}`;app.querySelector('h2').before(section);for(const kind of ['snapshot','merge','release'])section.querySelector(`#version-${kind}`)?.addEventListener('click',()=>{const key={snapshot:'versionSnapshotHistory',merge:'versionMergeHistory',release:'versionReleaseHistory'}[kind];state[key]??=[];show(`archive-version-${kind}`);});}
  if(archive&&state.storyClimaxComplete&&festivalReady(state.completed)){
   const section=document.createElement('section');section.className='panel';section.innerHTML=`<h2>文庫に届いた新しい依頼</h2><p>探し方を比べて、記録を探す手がかりを作りましょう。</p><button id="search-lab">棚の探し方を比べる${state.completed.includes('archive-search-lab')?'（達成済み）':''}</button>`;app.querySelector('h2').before(section);
   section.querySelector('#search-lab').onclick=()=>{state.searchHistory??=[];show('archive-search-lab');};
  }
  if(archive&&state.storyClimaxComplete&&festivalReady(state.completed)){const ready=['archive-utfmessage-ascii','archive-utfmessage-kana'].every(id=>state.completed.includes(id)),section=document.createElement('section');section.className='panel';section.innerHTML=`<h2>文字をバイトで届ける依頼</h2><p>アオイと文字のバイトを順番に並べましょう。</p><div class="actions"><button id="utfmessage-ascii">英字 A を届ける${state.completed.includes('archive-utfmessage-ascii')?'（達成済み）':''}</button><button id="utfmessage-kana">「あ」を届ける${state.completed.includes('archive-utfmessage-kana')?'（達成済み）':''}</button>${ready?`<button id="utfmessage-combine">文字の順とバイトを比べる${state.completed.includes('archive-utfmessage-combine')?'（達成済み）':''}</button>`:''}</div>${ready?'':'<p>二つの依頼を終えると、文字の順について相談が届きます。</p>'}`;app.querySelector('h2').before(section);for(const kind of ['ascii','kana','combine'])section.querySelector(`#utfmessage-${kind}`)?.addEventListener('click',()=>{const key={ascii:'utfmessageAsciiHistory',kana:'utfmessageKanaHistory',combine:'utfmessageCombineHistory'}[kind];state[key]??=[];show(`archive-utfmessage-${kind}`);});}
