 if(task&&p.phase===3)work=`<p>発送札には荷物の札番号だけを渡します。残す項目を選びましょう。</p><div class="actions"><button data-record="column:place">地名だけ</button><button data-record="column:id">荷物の札番号だけ</button><button data-record="column:all">すべての項目</button></div>`;
 app.innerHTML=`<h1>届け先の発送札を作る</h1>${dialogue('yuno','荷物と届け先の記録をつなぎ、各地に送る札を用意したいの。手伝ってくれる？')}<section class="panel"><h2>目標：三つの場面で発送札を作る</h2><p>荷物の表には札番号・届け先番号・準備状態があります。届け先の表には番号と地名があります。同じ番号を使って表を結び、準備済みで指定された地名に届く札を探します。</p><p>進み具合：${p.scene} / ${recordCases.length}</p>${task?`<h3 tabindex="-1">${p.scene+1}つ目：${task.target}へ届ける札</h3><h4>荷物の表</h4><ul>${displayRows}</ul><h4>届け先の表</h4><ul>${destinations}</ul>${work}`:`<h3 tabindex="-1">三つの発送札を作りました</h3><p>結果：${p.results.map((ids,i)=>`${i+1}つ目 ${ids.length?ids.join('・'):'該当なし'}`).join('、')}。</p><p>行を条件で選ぶ操作を選択、番号を手がかりに表を組み合わせる操作を結合、必要な項目だけ取り出す操作を射影といいます。</p><button id="record-restart">もう一度試す</button>`}<p id="record-status" role="status" tabindex="-1">${p.done?'目標を達成しました！':'記録を見て作業しましょう。'}</p>${warning()}<button id="record-back">谷の記録所へ戻る</button></section>${p.done?`<dialog id="success-dialog" class="story-success" aria-labelledby="record-success"><h2 id="record-success">依頼達成<span class="success-detail">届け先の発送札を作る</span></h2>${dialogue('yuno','届け先を確かめられたわ。ありがとう！')}${dialogue('nono','該当する札がないときも分かったね！')}<button id="record-finish" class="primary">結果を見る</button></dialog>`:''}`;
 const status=app.querySelector('#record-status'),firstAction=app.querySelector('[data-record]');if(firstAction)firstAction.before(status);
 const act=action=>{const next=[...history,action],value=replayRecords(next);if(!value){const hints=['準備済みの札をすべて選び、準備中の札は外しましょう。','荷物と届け先の番号が同じ組み合わせを選び、すべて結びましょう。','結んだ記録から指定の地名を探しましょう。該当がなければ何も選びません。','発送札には荷物の札番号だけが必要です。'];app.querySelector('#record-status').textContent=hints[p.phase];app.querySelector('#record-status').focus();return;}state.recordHistory=next;if(value.done&&!state.completed.includes('valley-query-lab'))state.completed.push('valley-query-lab');persist();recordLab();if(value.done)app.querySelector('#success-dialog').showModal();else{const changed=value.phase!==p.phase||value.scene!==p.scene;const same=changed?null:app.querySelector(`[data-record="${action}"]:not(:disabled)`);(same??app.querySelector('[data-record]:not(:disabled)')??app.querySelector('section.panel h3')).focus({preventScroll:true});}};
