 let body='';if(p.done)body=`<p>${summary}</p><p>${kind==='identity'?'検証の成功と、鍵が誰のものかの確認は別です。':'この模型で本文・鍵と署名の検証結果を確かめました。'}</p><button id="seal-signature-restart">もう一度試す</button>`;
 else {const message=sealSignatureMessages[task.caseId],needed=task.key==='mira'?'ミラ':'ノノ';body=`<h3>${p.scene+1}通目</h3><p>本文：「${message.text}」。${task.binding==='unverified'?'「ミラ」と書かれた鍵を提示されましたが、鍵の持ち主は未確認です。':'この場面では、名簿で鍵名と持ち主の対応が正しく確認されていると仮定します。'}</p><p>「${needed}」と書かれた鍵で検証しましょう。</p><div class="actions"><button data-seal-signature-action="key:nono" aria-pressed="${p.key==='nono'}">ノノと書かれた鍵</button><button data-seal-signature-action="key:mira" aria-pressed="${p.key==='mira'}">ミラと書かれた鍵</button><button data-seal-signature-action="verify">この鍵で検証</button></div><p>選んだ鍵：${p.key==='mira'?'ミラ':p.key==='nono'?'ノノ':'まだなし'}。検証結果：${p.verified===null?'まだなし':p.verified?'成功':'失敗'}。</p>${p.verified===null?'':kind==='identity'?'<p>ミラからの手紙と判断できますか？</p><div class="actions"><button data-seal-signature-action="answer:mira">ミラと判断できる</button><button data-seal-signature-action="answer:other">確認した鍵はノノのもの</button><button data-seal-signature-action="answer:unknown">鍵の持ち主が未確認で判断できない</button></div>':'<p>この鍵での検証結果を記録しましょう。</p><div class="actions"><button data-seal-signature-action="answer:invalid">失敗</button><button data-seal-signature-action="answer:valid">成功</button></div>'}<button data-seal-signature-action="reset">最初から試す</button>`;}
 app.innerHTML=`<h1>${title}</h1>${dialogue('shino','署名と鍵の関係を一緒に確かめましょう。')}<section class="panel"><h2>目標：${kind==='identity'?'検証結果と鍵の持ち主の確認を分けて考える':'２通の手紙を検証して結果を記録する'}</h2><p>デジタル署名は秘密鍵で作り、対応する公開鍵で本文と署名を検証します。この依頼の判定は、あらかじめ決められた手紙と鍵の模型で、実際の暗号計算は行いません。</p><p>検証の失敗だけでは、本文の変更・鍵の違い・署名の破損などの原因を一つに決められません。成功しても、鍵と人物の対応を別に確認しなければ本人を判断できません。</p>${body}${summary?`<p>これまでの結果：${summary}</p>`:''}<p id="seal-signature-status" role="status" tabindex="-1">${p.done?'目標を達成しました！':'手紙と鍵、検証結果を確かめましょう。'}</p><p>この例は鍵が安全に管理されていることや、手紙の内容が正しいことを保証しません。</p>${warning()}<p><button id="seal-signature-back">霧の関所へ戻る</button></p></section>${p.done?`<dialog id="success-dialog" class="story-success" aria-labelledby="seal-signature-success"><h2 id="seal-signature-success">依頼達成<span class="success-detail">${title}</span></h2><p>${summary}</p>${dialogue('shino','鍵と署名を確かめてくれてありがとう。')}<button id="seal-signature-finish" class="primary">結果を見る</button></dialog>`:''}`;
