 if(forge&&state.storyClimaxComplete&&festivalReady(state.completed)){const ready=['forge-io-poll','forge-io-interrupt'].every(id=>state.completed.includes(id)),section=document.createElement('section');section.className='panel';section.innerHTML=`<h2>装置の完成を受け取る依頼</h2><p>アカリと装置を待つ間の仕事を確かめましょう。</p><div class="actions"><button id="io-poll">装置の状態を見に行く${state.completed.includes('forge-io-poll')?'（達成済み）':''}</button><button id="io-interrupt">装置の知らせを受ける${state.completed.includes('forge-io-interrupt')?'（達成済み）':''}</button>${ready?`<button id="io-compare">二つの待ち方を比べる${state.completed.includes('forge-io-compare')?'（達成済み）':''}</button>`:''}</div>${ready?'':'<p>二つの依頼を終えると、待ち方を比べる相談が届きます。</p>'}`;app.querySelector('h2').before(section);for(const kind of ['poll','interrupt','compare'])section.querySelector(`#io-${kind}`)?.addEventListener('click',()=>{const key={poll:'ioPollHistory',interrupt:'ioInterruptHistory',compare:'ioCompareHistory'}[kind];state[key]??=[];show(`forge-io-${kind}`);});}
