 app.querySelectorAll('[data-performance-action]').forEach(button=>button.onclick=()=>act(button.dataset.performanceAction));app.querySelector('#performance-restart')?.addEventListener('click',()=>{state[key]=[];persist();performanceLab(kind);app.querySelector('#performance-status').focus({preventScroll:true});});app.querySelector('#performance-finish')?.addEventListener('click',()=>app.querySelector('#success-dialog').close());app.querySelector('#performance-back').onclick=()=>show('harbor');
