 app.querySelectorAll('[data-planning-action]').forEach(b=>b.onclick=()=>act(b.dataset.planningAction));app.querySelector('#planning-restart')?.addEventListener('click',()=>{state[key]=[];persist();planningLab(kind);app.querySelector('#planning-status').focus({preventScroll:true});});app.querySelector('#planning-finish')?.addEventListener('click',()=>app.querySelector('#success-dialog').close());app.querySelector('#planning-back').onclick=()=>show('observatory');
