 app.innerHTML=`<h1>${title}</h1>${dialogue('alto','知らせを守る仕組みを一緒に試してくれる？')}<section class="panel"><h2>目標：${kind==='digest'?'３つの摘要を比べる':kind==='encrypt'?'２つの鍵で開く':'変更前後を確かめる'}</h2><p>これは教材用の固定された知らせです。鍵などの例はこのブラウザに保存されます。実際の秘密や個人情報は入力しないでください。鍵の安全な共有や相手の本人確認はこの模型では扱いません。</p>${body}<p id="crypto-status" role="status" tabindex="-1">${p.done?'目標を達成しました！':'操作して確かめましょう。'}</p>${p.done?'<button id="crypto-restart">もう一度試す</button>':''}${warning()}<p><button id="crypto-back">空の中継塔へ戻る</button></p></section>${p.done?`<dialog id="success-dialog" class="story-success" aria-labelledby="crypto-success"><h2 id="crypto-success">依頼達成<span class="success-detail">${title}</span></h2>${dialogue('alto','知らせを守る仕組みを試してくれてありがとう！')}<button id="crypto-finish" class="primary">結果を見る</button></dialog>`:''}`;
 let busy=false;const act=async action=>{if(busy)return;busy=true;app.querySelectorAll('button').forEach(button=>button.disabled=true);const status=app.querySelector('#crypto-status');status.textContent='計算しています。';
  try{let recorded=action;if(action==='seal'){const packet=await makeDemoPacket();recorded=`sealed:${packet.key}:${packet.iv}:${packet.ciphertext}`;}else if(action.startsWith('digest:')){const index=Number(action.slice(7));recorded=`digest:${index}:${await demoDigest(index)}`;}else if(['wrong','right','changed'].includes(action)){const result=await openDemoPacket(p.packet,{wrong:action==='wrong',modified:action==='changed'});if(action==='right'?(!result.ok||result.text!=='灯りを届けて'):result.ok)throw Error('unexpected result');}
   const next=[...history,recorded],value=replayCrypto(kind,next);if(!value)throw Error('invalid operation');state[key]=next;if(value.done&&!state.completed.includes(id))state.completed.push(id);persist();cryptoLab(kind);if(value.done)app.querySelector('#success-dialog').showModal();else{const nextStatus=app.querySelector('#crypto-status');nextStatus.textContent='計算結果を表示しました。';nextStatus.focus({preventScroll:true});}
  }catch{cryptoLab(kind);const nextStatus=app.querySelector('#crypto-status');nextStatus.textContent='計算できませんでした。ブラウザの暗号機能を使える環境で、もう一度試してください。';nextStatus.focus();}finally{busy=false;}};
