 const label=id=>id===null?'空':`${s.nodes[id].key}${String(id)!==String(s.nodes[id].key)?`（元の場所${id}）`:''}`,tree=id=>id===null?'空':`<p>根：${label(id)}。</p><ul>${Object.keys(s.nodes).map(n=>`<li>番号${label(n)}：左 ${label(s.nodes[n].left)}、右 ${label(s.nodes[n].right)}</li>`).join('')}</ul>`;
