 app.innerHTML=`<h1>${title}</h1>${dialogue('marta','旅人に使いやすい掲示板を作りたいの。一緒に話を聞いてくれる？')}<section class="panel"><h2>目標：${kind==='interview'?'６つの発言を整理する':kind==='story'?'二人の話を組み立てる':'質問して合意を試す'}</h2><p>${kind==='interview'?'配置済み':'進み具合'}：${progress}${kind==='interview'&&!p.done?'（内容は「確かめる」で確認）':''}</p><p>${intro}</p>${body}<p id="requirements-status" role="status" tabindex="-1">${p.done?'目標を達成しました！':'操作してから確かめましょう。'}</p>${p.done?'<button id="requirements-restart">もう一度試す</button>':`<p><button id="requirements-check" class="primary">${kind==='agreement'&&p.scene===0?'答えを聞いて約束を確かめる':'確かめる'}</button></p>`}${warning()}<p><button id="requirements-back">${fourRegions.guide.name}へ戻る</button></p></section>${p.done?`<dialog id="success-dialog" class="story-success" aria-labelledby="requirements-success"><h2 id="requirements-success">依頼達成<span class="success-detail">${title}</span></h2>${dialogue('marta','旅人の声を大切に考えてくれて、ありがとう！')}<button id="requirements-finish" class="primary">結果を見る</button></dialog>`:''}`;
