 app.querySelectorAll('[data-requirements-pick]').forEach(b=>b.onclick=()=>{requirementsPick=b.dataset.requirementsPick;requirementsLab(kind);app.querySelector(`[data-requirements-pick="${requirementsPick}"]`)?.focus({preventScroll:true});});app.querySelectorAll('[data-requirements-place]').forEach(b=>b.onclick=()=>{if(requirementsPick===null){const status=app.querySelector('#requirements-status');status.textContent='先に発言札を選びましょう。';status.focus();return;}act(`place:${requirementsPick}:${b.dataset.requirementsPlace}`);app.querySelector(`[data-requirements-place="${b.dataset.requirementsPlace}"]`)?.focus({preventScroll:true});});app.querySelectorAll('[data-requirements-action]').forEach(b=>b.onclick=()=>act(b.dataset.requirementsAction));app.querySelector('#requirements-check')?.addEventListener('click',()=>act('check'));app.querySelector('#requirements-restart')?.addEventListener('click',()=>{state[key]=[];requirementsPick=null;persist();requirementsLab(kind);app.querySelector('#requirements-status').focus();});app.querySelector('#requirements-finish')?.addEventListener('click',()=>app.querySelector('#success-dialog').close());app.querySelector('#requirements-back').onclick=()=>{requirementsPick=null;show('guide');};
