 app.innerHTML=`<h1>${title}</h1>${dialogue('sena','観測記録のばらつきも一緒に調べよう。')}<section class="panel"><h2>目標：${cases.length}組の記録を調べる</h2><p>進み具合：${p.scene} / ${cases.length}</p><p>${intro}</p><p>${method}</p>${body}<p id="variance-status" role="status" tabindex="-1">${p.done?'目標を達成しました！':'記録を見て選びましょう。'}</p>${p.done?'<button id="variance-restart">もう一度試す</button>':`<button data-variance-action="check" class="primary">確かめる</button><button data-variance-action="reset">この記録を最初から</button>`}${warning()}<p><button id="variance-back">夢見の観測所へ戻る</button></p></section>${p.done?`<dialog id="success-dialog" class="story-success" aria-labelledby="variance-success"><h2 id="variance-success">依頼達成<span class="success-detail">${title}</span></h2><p>${kind==='deviation'?'平均との差の正負は打ち消し合います。':kind==='variance'?'差の２乗を平均して、母分散を求めました。':'同じ平均でも分散が異なる記録を比べました。'}</p>${dialogue('sena','一緒に調べてくれてありがとう！')}<button id="variance-finish" class="primary">結果を見る</button></dialog>`:''}`;
 const act=action=>{const next=[...history,action],value=replayVariance(kind,next);if(!value){const status=app.querySelector('#variance-status');status.textContent=kind==='deviation'?'その日の数から平均を引きましょう。全部選んでから確かめます。':kind==='variance'?'平均との差の２乗を求め、合計を４で割りましょう。':'２乗の合計をそれぞれ４で割って比べましょう。';status.focus({preventScroll:true});return;}state[key]=next;if(value.done&&!state.completed.includes(id))state.completed.push(id);persist();varianceLab(kind);if(value.done)app.querySelector('#success-dialog').showModal();else{const status=app.querySelector('#variance-status');status.textContent=action==='check'?'次の記録を調べましょう。':action==='reset'?'この記録を最初に戻しました。':'選びました。続きを調べましょう。';status.focus({preventScroll:true});}};
 app.querySelectorAll('[data-variance-action]').forEach(b=>b.onclick=()=>act(b.dataset.varianceAction));app.querySelector('#variance-restart')?.addEventListener('click',()=>{state[key]=[];persist();varianceLab(kind);app.querySelector('#variance-status').focus({preventScroll:true});});app.querySelector('#variance-finish')?.addEventListener('click',()=>app.querySelector('#success-dialog').close());app.querySelector('#variance-back').onclick=()=>show('observatory');
