 const key=kind==='collection'?'privacyCollectionHistory':kind==='identity'?'privacyIdentityHistory':'privacySafeguardsHistory',id=kind==='collection'?'guide-privacy-collection':kind==='identity'?'guide-privacy-identity':'guide-privacy-safeguards',title=kind==='collection'?'薬草の受取帳を整える':kind==='identity'?'番号の札を確かめる':'受取帳の公開を考える';
