 app.innerHTML=`<h1>${title}</h1>${dialogue('marta','旅人の記録を大切に扱いたいの。一緒に確かめてくれる？')}<section class="panel"><h2>目標：三つの場面を確かめる</h2><p>進み具合：${p.scene} / 3</p>${scene?`<h3>${p.scene+1}つ目の場面</h3><p>${scene.prompt}</p><p id="privacy-status" role="status" tabindex="-1">${selected>=0?scene.effects[selected]:'選んでから確かめましょう。'}</p><div class="actions">${scene.options.map((v,i)=>`<button data-privacy-choice="${v}" aria-pressed="${p.choice===v}">${scene.labels[i]}</button>`).join('')}</div><p><button id="privacy-check" class="primary">確かめる</button></p>`:`<h3>三つの場面を確かめました</h3><p>${kind==='collection'?'目的に必要な情報を選び、見られる人と保存する期間も考えました。必要性や本人の希望は状況により異なります。':'番号に置き換えても対応表があれば本人に結びつきます。集計でも他の情報から推測される場合があります。匿名性は状況を調べる必要があります。'}</p><p id="privacy-status" role="status" tabindex="-1">目標を達成しました！</p><button id="privacy-restart">もう一度試す</button>`}${warning()}<p><button id="privacy-back">${fourRegions.guide.name}へ戻る</button></p></section>${p.done?`<dialog id="success-dialog" class="story-success" aria-labelledby="privacy-success"><h2 id="privacy-success">依頼達成<span class="success-detail">${title}</span></h2>${dialogue('marta','旅人の記録について考えてくれて、ありがとう！')}<button id="privacy-finish" class="primary">結果を見る</button></dialog>`:''}`;
