 const act=action=>{const next=[...history,action],value=replayRecovery(next);if(!value){const status=app.querySelector('#recovery-status');status.textContent=p.stage===1?'規則違反の知らせは、利用を保留しましょう。':p.stage===2?'控えとの完全一致と、点灯数が偶数であることの両方を確かめましょう。':p.stage===5?'二枚が変わった場合の届いた札と控えを見比べましょう。':'今の段階を確かめましょう。';status.focus();return;}state.recoveryHistory=next;if(value.done&&!state.completed.includes('windmill-recovery'))state.completed.push('windmill-recovery');persist();recoveryLab();if(value.done)app.querySelector('#success-dialog').showModal();else{const status=app.querySelector('#recovery-status');status.textContent=action.startsWith('flip:')?`${Number(action.slice(5))+1}枚目を${value.lamps[Number(action.slice(5))]?'点灯':'消灯'}にしました。`:action==='inspect'?(p.stage===0?'点灯１枚、奇数で規則違反です。':'点灯２枚で偶数ですが、控えとは異なります。'):action==='hold'?'知らせの利用を保留しました。':action==='verify'?'控えとの一致と偶数を確認しました。':'利用を再開しました。';status.focus();}};
