 app.innerHTML=`<h1>${title}</h1>${dialogue('mizuho','水門の道具に合う札を、一緒に確かめてもらえる？')}<section class="panel"><h2>目標：${branch?'五つの点検を比べる':kind==='record'?'二つの点検票を作る':'四つの道具を試す'}</h2><p>進み具合：${p.scene} / ${count}</p><p id="type-status" role="status" tabindex="-1">${p.done?'目標を達成しました！':'場面の目標を確かめましょう。'}</p>${results.length?`<h3>これまでの結果</h3><ol>${results.map(r=>`<li>${r}</li>`).join('')}</ol>`:''}${content}${p.done?'<button id="type-restart">もう一度試す</button>':''}${warning()}<p><button id="type-back">水辺の村へ戻る</button></p></section>${p.done?`<dialog id="success-dialog" class="story-success" aria-labelledby="type-success"><h2 id="type-success">依頼達成<span class="success-detail">${title}</span></h2><p>最後の結果：${results.at(-1)}</p>${dialogue('mizuho','水門の点検を手伝ってくれてありがとう！')}${dialogue('nono','札の種類を確かめるのが大切なんだね。')}<button id="type-finish" class="primary">結果を見る</button></dialog>`:''}`;
