 app.querySelectorAll('[data-type-action]').forEach(b=>b.onclick=()=>act(b.dataset.typeAction));app.querySelector('#type-run')?.addEventListener('click',()=>act('run'));app.querySelector('#type-restart')?.addEventListener('click',()=>{state[key]=[];persist();typeLab(place);app.querySelector('#type-status').focus();});app.querySelector('#type-finish')?.addEventListener('click',()=>app.querySelector('#success-dialog').close());app.querySelector('#type-back').onclick=()=>show('river');
