const newRegionNames={workshop:'精霊の工房',archive:'森の文庫',windmill:'風車の里',valley:'谷の記録所',station:'風待ちの駅',river:'水辺の村',harbor:'風の港町',garden:'星読みの庭園',guide:'旅人の案内所',observatory:'夢見の観測所'};
