function newActivity(id,scenario,selected,index){
 if(id!=='garden-mosaic')return '';
 const colors=index===0?['青','黄']:['赤','白'];
 const positions=['左','真ん中','右'];
 const chosen=new Set(selected.map(i=>positions.findIndex(pos=>scenario.choices[i].startsWith(pos))));
 return `<div class="mosaic-preview" aria-live="polite"><strong>作っている花壇の絵</strong><div class="mosaic-row">${positions.map((pos,i)=>{const color=chosen.has(i)?colors[1]:colors[0];return `<span class="mosaic-cell mosaic-${color==='青'?'blue':color==='黄'?'yellow':color==='赤'?'red':'white'}">${pos}<br>${color}</span>`;}).join('')}</div></div>`;
}
